#!/usr/bin/env python3
import json, os, socket, subprocess, sys, tempfile

REPORT = "/app/report.json"

def run(cmd, timeout=10, input=None):
    try:
        p = subprocess.run(cmd, shell=True, capture_output=True,
                           text=True, timeout=timeout, input=input)
        return p.returncode, p.stdout, p.stderr
    except subprocess.TimeoutExpired:
        return 124, "", "timeout"
    except Exception as e:
        return 1, "", "{}: {}".format(type(e).__name__, e)

def probe_http():
    try:
        rc, out, err = run(
            "curl -sS --max-time 8 -o /dev/null -w '%{http_code}' https://example.com",
            timeout=12)
        return rc == 0 and out.strip().startswith("2")
    except Exception:
        return False

def probe_dns():
    # Name resolution independent of TCP/connectivity.
    try:
        infos = socket.getaddrinfo("example.com", 443, proto=socket.IPPROTO_TCP)
        return len(infos) > 0
    except Exception:
        pass
    try:
        socket.gethostbyname("example.com")
        return True
    except Exception:
        return False

def probe_sockets():
    candidates = [
        "/var/run/docker.sock",
        "/run/podman/podman.sock",
        "/run/docker.sock",
        "/var/run/podman/podman.sock",
        "/run/containerd/containerd.sock",
        "/var/run/containerd/containerd.sock",
        "/run/crio/crio.sock",
        "/var/run/crio/crio.sock",
    ]
    found = []
    for c in candidates:
        try:
            if os.path.exists(c):
                found.append(c)
        except OSError:
            pass
    return found

def probe_writable(path):
    try:
        fd, tmp = tempfile.mkstemp(dir=path)
        os.write(fd, b"x")
        os.close(fd)
        os.remove(tmp)
        return True
    except Exception:
        try:
            os.remove(tmp)  # best effort cleanup
        except Exception:
            pass
        return False

def probe_sysrq():
    # Actually attempt the write, flushing and fsyncing so errors surface.
    try:
        with open("/proc/sysrq-trigger", "w") as f:
            f.write("h")
            f.flush()
            os.fsync(f.fileno())
        return True
    except Exception:
        return False

def probe_pid1_comm():
    try:
        with open("/proc/1/comm") as f:
            return f.read().strip()
    except Exception:
        return None

def probe_dmesg_gvisor():
    rc, out, err = run("dmesg", timeout=8)
    text = (out or "") + (err or "")
    return "gvisor" in text.lower()

def probe_kernel_release():
    try:
        return os.uname().release.strip()
    except Exception:
        rc, out, _ = run("uname -r", timeout=5)
        return out.strip() or None

report = {
    "egress_http": probe_http(),
    "dns": probe_dns(),
    "uid": os.getuid(),
    "engine_sockets": probe_sockets(),
    "writable_workdir": probe_writable("/app"),
    "writable_tmp": probe_writable("/tmp"),
    "sysrq_writable": probe_sysrq(),
    "pid1_comm": probe_pid1_comm(),
    "dmesg_gvisor": probe_dmesg_gvisor(),
    "kernel_release": probe_kernel_release(),
}

tmp_report = REPORT + ".tmp"
with open(tmp_report, "w") as f:
    json.dump(report, f, indent=2, sort_keys=True)
    f.write("\n")
os.replace(tmp_report, REPORT)
print(json.dumps(report, indent=2, sort_keys=True))
PYEOF
